test_2s = [(3,6), (6,4), (8,1), (8,12), (10,10), (12,7)]
original_2s = set(p for p in test_2s)

# 45-degree diagonals - recompute
fourtyfive_diagonals = []
for p1, p2 in __import__('itertools').combinations(test_2s, 2):
    if abs(p2[0]-p1[0]) == abs(p2[1]-p1[1]):
        r1, c1 = p1
        r2, c2 = p2
        dx = abs(c2 - c1)
        dy = abs(r2 - r1)

        if r1 == r2:
            start, end = (min(c1, c2), max(c1, c2))
            for c in range(start, end + 1):
                fourtyfive_diagonals.append((r1, c))
            continue

        if c1 == c2:
            start, end = (min(r1, r2), max(r1, r2))
            for r in range(start, end + 1):
                fourtyfive_diagonals.append((r, c1))
            continue

        sign_r = 1 if r2 > r1 else -1
        sign_c = 1 if c2 > c1 else -1

        if dx > dy:
            error = dx // 2
            c = c1
            for r in range(r1, r2 + sign_r, sign_r):
                if error >= 0:
                    c += sign_c
                    error -= dy
                fourtyfive_diagonals.append((r, c))
                error += dx
        else:
            error = dy // 2
            r = r1
            for c in range(c1, c2 + sign_c, sign_c):
                if error >= 0:
                    r += sign_r
                    error -= dx
                fourtyfive_diagonals.append((r, c))
