from itertools import combinations

def bresenham(r1, c1, r2, c2):
    """Return all points on 45-degree diagonal line segment"""
    if abs(r2-r1) != abs(c2-c1):
        return set()  # Not a 45-degree diagonal

    pts = []
    if r1 == r2:
        for c in range(min(c1,c2), max(c1,c2)+1):
            pts.append((r1, c))
        return set(pts)
    if c1 == c2:
        for r in range(min(r1,r2), max(r1,r2)+1):
            pts.append((r, c1))
        return set(pts)

    dr = 1 if r2 > r1 else -1
    dc = 1 if c2 > c1 else -1

    err = abs(c2-c1) // 2
    for r in range(r1, r2 + dr, dr):
        if err >= 0:
            c = c1
            err -= abs(r2-r1)
        pts.append((r, c))
        err += abs(r2-r1)

    return set(pts)

