from itertools import combinations

def diagonals_bresenham(p1, p2):
    r1, c1 = p1
    r2, c2 = p2

    if abs(r2-r1) != abs(c2-c1):
        return set()

    if r1 - c1 == r2 - c2:
        k = r1 - c1
        pts = set()
        for c in range(0, 17):
            r = c + k
            if 0 <= r < 14 and 0 <= c < 17:
                pts.add((r, c))
        return pts
    else:
        k = r1 + c1
        pts = set()
        for r in range(0, 14):
            c = k - r
            if 0 <= c < 17:
                pts.add((r, c))
        return pts

